entries[1295404] = { ["name"] = "Spotted Killifish", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nSpotted Killifish demonstrate a remarkable ability to adapt to any environment, regardless of what type of pollutants it swims in.\n\nSpecial:\n\nPerceptive Chum\n\nThrow the catch back into the water to gain 25 Midnight Perception for 30 sec.\n\nThrowing multiple catches can extend this buff up to 5 min.\n\nAreas you can find this fish:\n- The Coiled Isle\n\nFishing Pools:\n- Bubbling Beryl\n- Willow Sea\n- Viscous Venom\n\nRates:\n- This fish is exceedingly common in open water." }
entries[1295405] = { ["name"] = "Toxic Tlhapi", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nA lean, nutrient-dense fish whose adaptations have made it much too dangerous to eat without careful preparations from an intending chef.\n\nSpecial:\n\nSkillful Chum\n\nThrow this catch back into the water to gain 25 Midnight Fishing for 30 sec.\n\nThrowing multiple catches can extend this buff up to 5 min. Only active in Midnight zones.\n\nAreas you can find this fish:\n- The Coiled Isle\n\nFishing Pools:\n- Bubbling Beryl\n- Willow Sea\n- Viscous Venom\n\nRates:\n- This fish is exceedingly common in open water." }
entries[1295406] = { ["name"] = "Ula'tek Snakehead", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nA fish with a striking resemblance to the serpentine monster Ula'tek, this predator sits atop the food pyramid looking down on fish and foe alike. Vibrant cerulean scales adorned with feathers coil into its primary habitat, the Temple of Ula'tek.\n\nSpecial:\n\nCooking\n\nThis rare and tasty fish is an important ingredient in several Midnight Cooking recipes.\n\nAreas you can find this fish:\n- Vaults of Ula'tek\n\nFishing Pools:\n- Bubbling Beryl\n- Willow Sea\n- Viscous Venom\n\nRates:\n- This fish is mostly found in pools inside the Temple of Ula'tek.\n- This fish can also be caught around The Coiled Isle with a lure." }
entries[1295407] = { ["name"] = "Sulfurous Sludgefish", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nA particularly slimy denizen of The Coiled Isle. Its primary adaptation is the sludge coating by which it gets its name. This coating obscures itself from predators and prey alike.\n\nSpecial:\n\nSludge Coating\n\nRub the sludgefish over your body, reducing your chance of being detected by enemies on Atal'Utek for 5 min.\n\nAreas you can find this fish:\n- The Coiled Isle\n\nFishing Pools:\n- Bubbling Beryl\n\nRates:\n- This fish is exceedingly common in pools." }
entries[1295408] = { ["name"] = "Coiled Stargorger", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nA creature of indescribable awe, mostly due to its edges blurring when you look straight at it. Its favorite food is starfish, and we're not sure what you expected.\n\nSpecial:\n\nCooking\n\nThis rare and tasty fish is an important ingredient in several Midnight Cooking recipes.\n\nAreas you can find this fish:\n- Atal'Utek\n\nFishing Pools:\n- Torrential Gorgerswarm\n\nRates:\n- This fish is mostly found in pools." }
entries[1295409] = { ["name"] = "Dirty Darter", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nAdept in the particularly perilous waters of The Coiled Isle, this minnow isn't afraid to get messy when it comes to survival. Darting between crevices, sinking into coagulated venom, or simply being faster than its predators, this fish does what it takes to survive. However, it's no match for a juicy line.\n\nSpecial:\n\nSurface Tension\n\nThrow the catch back and gain the ability to walk on water for 30 sec.\n\nThrowing multiple catches can extend this buff up to 5 min. Only active in Midnight zones.\n\nAreas you can find this fish:\n- The Coiled Isle\n\nFishing Pools:\n- Bubbling Beryl\n- Willow Sea\n- Viscous Venom\n\nRates:\n- This fish is exceedingly common in open water." }
entries[1295410] = { ["name"] = "Polluted Puffer", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nA quirky specimen of The Coiled Isle, the Polluted Puffer houses many hidden spines that only make themselves apparent when threatened. In such cases, the fish inflates its body jutting the spines outward.\n\nSpecial:\n\nCooking\n\nThis rare and tasty fish is an important ingredient in several Midnight Cooking recipes.\n\nAreas you can find this fish:\n- The Coiled Isle\n\nFishing Pools:\n- Willow Sea\n\nRates:\n- This fish is exceedingly common in pools." }
entries[1295411] = { ["name"] = "Blightswarmer", ["text"] = "5 yd range\n3.2 sec cast\nAnglin' Score: points.\n\nCatch Rank: Guppy\n\nDescription:\nAn opportunistic predator, this eel derives it's name from the sheer amount present in Cursed Waters. As the waters turn sour its primal instincts take over.\n\nSpecial:\n\nCooking\n\nThis rare and tasty fish is an important ingredient in several Midnight Cooking recipes.\n\nAreas you can find this fish:\n- The Coiled Isle\n\nRates:\n- This fish is only found in the Cursed Waters after a Venom Surge in The Coiled Isle." }
