entries[1295420] = { ["name"] = "The Coiled Isle", ["text"] = "Instant\nRecommended Skill: 100\n\nEast of Zul'Aman exists a series of islands that wrap around Ula'tek Temple like a coiled snake. Venom seeps from the temple into the surrounding waters, warping the ecology with it.\n\nPools found in this zone:\n- Bubbling Beryl\n- Willow Sea\n- Viscous Venom\n- Vile Venom\n- Vile Oddities\nProfession:\nFishing (75)" }
entries[1295421] = { ["name"] = "Venom Fishing", ["text"] = "Instant\nRecommended Skill: 225\n\nImbued within The Coiled Isle are rivers of acidic venom certain to thwart successful fishing attempts from even the most seasoned anglers.\n\nPools found in this zone:\n- Bubbling Beryl\n- Willow Sea\n- Viscous Venom\n- Vile Venom\n- Vile Oddities" }
entries[1295422] = { ["name"] = "Temple Fishing", ["text"] = "Instant\nRecommended Skill: 300\n\nSitting atop The Coiled Isle is a place few anglers are willing to cast their line. Coalesced venom imbues the creatures lurking below. These oddities are grotesque and vile.\n\nPools found in this zone:\n- Viscous Venom\n- Vile Venom\n- Vile Oddities" }
entries[1295423] = { ["name"] = "Torrential Gorgerswarm", ["text"] = "15 yd range\nInstant\nThrow the lure into any Atal'Utek fishing pool to turn it into a Torrential Gorgerswarm. This destroys the pool in the process.\n\nThe decomposition of the starfish attracts Coiled Stargorgers to the pool." }
